# pattern: Imperative Shell
"""Dump TITLE_WHITESPACE as a TS artifact, so the web folds a title's
whitespace runs by the same list the server does:
uv run python -m pkm.title_whitespace_dump \\
    > ../web/src/grammar/titleWhitespace.gen.ts
Every character is written as a \\uXXXX escape, so none of the invisible
ones can be lost or swapped in an editor. Guarded by
tests/test_title_whitespace_artifact.py (same pattern as schema_dump)."""
from __future__ import annotations

from pkm.contracts.titles import TITLE_WHITESPACE

HEADER = (
    "// GENERATED by `uv run python -m pkm.title_whitespace_dump` (server/src/"
    "pkm/title_whitespace_dump.py).\n// Do not edit; regenerate when "
    "contracts/titles.py TITLE_WHITESPACE changes (server test enforces).\n")


def ts_module(chars: str) -> str:
    escaped = "".join(f"\\u{ord(c):04x}" for c in chars)
    return f'{HEADER}export const TITLE_WHITESPACE = "{escaped}";\n'


def main() -> int:
    print(ts_module(TITLE_WHITESPACE), end="")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
